{
  "name": "@statusline/core",
  "version": "1.2.0",
  "description": "Core library for the agent status line: section-priority layout, Unicode-aware width and CLI, OpenCode, VS Code and Neovim renderers",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    },
    "./package.json": "./package.json"
  },
  "scripts": {
    "build": "tsc",
    "test": "vitest run",
    "dev": "tsc --watch"
  },
  "keywords": [
    "statusline",
    "status-line",
    "claude-code",
    "cursor",
    "opencode",
    "cli",
    "rendering",
    "tui"
  ],
  "author": "S. Strebulaev",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/sergemso/ai-tools.agent-status-line.git",
    "directory": "packages/core"
  },
  "bugs": {
    "url": "https://github.com/sergemso/ai-tools.agent-status-line/issues"
  },
  "homepage": "https://github.com/sergemso/ai-tools.agent-status-line/tree/main/packages/core#readme",
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "files": [
    "dist/",
    "README.md"
  ],
  "devDependencies": {
    "typescript": "^5.3.0",
    "vitest": "^1.0.0"
  },
  "peerDependencies": {
    "typescript": "^5.0.0"
  },
  "engines": {
    "node": ">=18.0.0"
  }
}
